insert into public.courses (id, language, dialect, title, description, cefr_level, goal_tag, position, published, school, prerequisite_ids)
values ('bbbb0005-0000-4000-8000-000000000020', 'en', null, 'Theory of Knowledge', 'Theory of Knowledge is the core course at the heart of the International Baccalaureate (IB) Diploma, and it asks not what we know but how we know it. Across ten lessons you will explore knowledge questions, the ways of knowing, and the areas of knowledge, keeping the tone exploratory and balanced rather than dictating answers. Structure and background adapted from Wikipedia, the free encyclopedia (CC BY-SA 4.0).', null, 'foundations', 78, true, 'humanities', '{}')
on conflict (id) do nothing;

insert into public.lessons (course_id, position, title, kind, body, grammar_notes_md, estimated_minutes)
select 'bbbb0005-0000-4000-8000-000000000020', v.pos, v.title, v.kind, v.body::jsonb, v.notes, v.mins
from (values
  (1, 'Diagnostic: how do you know what you know?', 'quiz', '{"questions":[{"prompt":"In Theory of Knowledge, a ''knowledge question'' is best described as...","options":["a factual question with one correct answer","an open question about how knowledge is built, judged, or justified","a question only experts are allowed to answer","a trick question that has no answer at all"],"answer":1,"explanation":"Knowledge questions step back from the facts to ask how knowing works - they are open and contestable."},{"prompt":"The traditional definition of knowledge as ''justified true belief'' requires a belief that is...","options":["popular and old","true, believed, and supported by good reasons","written down by an authority","impossible to doubt in any way"],"answer":1,"explanation":"All three parts - truth, belief, and justification - must hold together."},{"prompt":"Shared knowledge and personal knowledge differ roughly in that...","options":["shared knowledge is always false","shared knowledge is built by communities while personal knowledge comes from individual experience","personal knowledge can never be mistaken","they are simply two names for the same thing"],"answer":1,"explanation":"Communities build and check shared knowledge; personal knowledge grows from one knower''s own experience."},{"prompt":"Which of these is usually treated as a ''way of knowing'' in this course?","options":["a library","sense perception","a textbook","a diploma"],"answer":1,"explanation":"Ways of knowing are tools such as reason, perception, and language - not the places or objects that store knowledge."},{"prompt":"Which of these is an ''area of knowledge'' in this course?","options":["the natural sciences","a search engine","a filing cabinet","a classroom"],"answer":0,"explanation":"Areas of knowledge are large fields such as the sciences, history, and the arts, each with its own methods."},{"prompt":"A key limit of sense perception is that...","options":["our senses never work at all","perception can be shaped by expectation and fooled by illusions","only machines are able to perceive","perception is always perfectly accurate"],"answer":1,"explanation":"Illusions fool everyone and expectation steers what we notice, so a single look is not enough."},{"prompt":"Confirmation bias is the tendency to...","options":["seek and favor evidence that fits what we already believe","trust complete strangers without question","forget everything we once learned","reason without ever making a mistake"],"answer":0,"explanation":"We tend to notice and keep evidence that supports our existing view, and to discount the rest."},{"prompt":"When evaluating a claim, a sound first step is to ask...","options":["who is saying it most loudly","what the evidence is and how reliable the source is","whether it is currently popular","whether it sounds new and exciting"],"answer":1,"explanation":"Start with the evidence and the reliability of the source, not with volume, popularity, or novelty."}]}'::jsonb, null, 10),
  (2, 'What Theory of Knowledge is, and the knowledge question', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Explain what Theory of Knowledge, the core course of the International Baccalaureate, sets out to do, and tell the difference between an ordinary factual question and a knowledge question. Warm-up: is ''What is the capital of France?'' the kind of question this course spends its time on, or is it something different?"},{"heading":"The idea","text":"This course does not teach a body of facts to memorize. Instead it asks how knowledge is made, tested, shared, and trusted. A first-order question asks about the world directly: how far away is the Moon, who wrote a poem, is a treatment safe. A knowledge question steps back and asks about knowing itself: how do we decide whether a measurement is reliable, what counts as good evidence in science compared with history, can an expert be wrong. Knowledge questions are open, inviting careful discussion rather than a single lookup. They are general, pointing beyond one case to the wider practice of knowing. And they are contestable, meaning thoughtful people can disagree and defend different answers. The course organizes its thinking around ways of knowing, such as reason, perception, and language, and areas of knowledge, such as science, history, and the arts. Throughout, the aim is to be curious and balanced - to raise good questions and weigh reasons, not to hand down verdicts."},{"heading":"Key ideas & thinkers","text":"The study of knowledge is called epistemology, from Greek roots meaning knowledge and account. Plato set an early marker by asking, in the Theaetetus, how knowledge differs from mere opinion. Socrates modeled the habit of questioning assumptions until hidden confusions surface - a method this course still borrows. Later thinkers split over where knowledge begins: rationalists such as Descartes trusted reason as the firmest ground, while empiricists such as Locke and Hume traced knowledge back to experience and observation. Kant argued that the mind is not a blank page but actively shapes what we perceive. In the twentieth century, Karl Popper argued that scientific claims earn their standing by being testable and open to being proven wrong. These names are not a list to worship; they are voices in a long conversation you are joining. Meeting them shows that the question ''how do we know?'' is old, serious, and still unsettled, and that your own answers can enter the same discussion."},{"heading":"Your turn","text":"Sort each as a first-order question (F) or a knowledge question (K). 1) How many planets orbit the Sun? 2) How do astronomers decide a measurement is trustworthy? 3) Who painted the Mona Lisa? 4) Can a work of art tell us something true that a report cannot? 5) Is this historical source reliable? 6) In what year did the war end? Answers: 1) F. 2) K. 3) F. 4) K. 5) K. 6) F. Now, for one of the K items above, write a single sentence giving a reason someone might answer it one way, and a reason someone might answer it differently."},{"heading":"Common mistakes & exit ticket","text":"Mistake: treating a knowledge question as if it had one correct lookup answer - that collapses the very discussion the course wants. Mistake: thinking ''balanced'' means refusing to reach any view at all; balance means weighing reasons honestly and then holding your view open to challenge. Exit: (a) In one sentence, how does a knowledge question differ from a factual question? (b) Name one way of knowing and one area of knowledge. Answers: a knowledge question asks how we know or judge and is open and contestable, while a factual question asks directly about the world and usually has a settled answer; for example, reason is a way of knowing and history is an area of knowledge."}]}'::jsonb, 'In this course, treat ''knowledge'' as a verb as much as a noun - the focus is on knowing, not just on facts.', 13),
  (3, 'Shared knowledge and personal knowledge', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Tell apart shared knowledge and personal knowledge, give examples of each, and explain how the two constantly feed into one another. Warm-up: how much of what you say you ''know'' did you work out yourself, and how much did you take on trust from other people?"},{"heading":"The idea","text":"This course draws a useful line between two kinds of knowledge. Shared knowledge is built by groups over time: it is the product of many people checking, arguing, publishing, and correcting one another. The periodic table, the rules of grammar, a country''s recorded history, and a sport''s rulebook are all shared knowledge. No single person made them, and they outlast any individual. Personal knowledge is what a particular knower holds through their own experience, practice, and reflection: how to ride a bicycle, the feel of your home town, the skill of a craft you have practiced for years. The two are not sealed off from each other. Shared knowledge reaches you through teachers, books, and communities, and then becomes part of your personal understanding. Running the other way, personal insights - a researcher''s hunch, a witness account, an artist''s new technique - can be tested, refined, and absorbed back into the shared store. Asking which kind of knowledge a claim is, and how it got there, is one of the most useful moves in the whole course."},{"heading":"Key ideas & thinkers","text":"Thinking about shared knowledge means thinking about communities of knowers. A community sets methods - how a claim is checked - and standards - how good the evidence must be before the claim is accepted. Scientists use peer review and replication; historians weigh and cross-check sources; courts follow rules of evidence. These shared methods are powerful because they catch mistakes a single person would miss, but they also carry the assumptions of their community, which is why shared knowledge can still need revision. The sociologist Robert Merton described norms meant to keep shared knowledge honest, such as sharing results openly and judging claims on their merits rather than on who made them. For personal knowledge, the philosopher Michael Polanyi pointed to tacit knowledge - things we know how to do but cannot fully put into words, like recognizing a face or keeping our balance. Both ideas remind us that knowledge is a human activity, carried by people and groups, not a set of facts sitting on a shelf."},{"heading":"Your turn","text":"Label each as mainly shared (S) or mainly personal (P). 1) The boiling point of water at sea level. 2) How it feels to speak your first language. 3) The dates of a historical treaty. 4) Your sense of when a friend is upset. 5) The rules of chess. 6) A particular doctor''s bedside manner. Answers: 1) S. 2) P. 3) S. 4) P. 5) S. 6) P. Now pick one of your P answers and explain how it could feed into shared knowledge if it were recorded and tested by others."},{"heading":"Common mistakes & exit ticket","text":"Mistake: treating shared knowledge as finished and beyond question - communities revise it as methods improve. Mistake: treating personal knowledge as always private and untestable, when much of it can in fact be checked and shared. Exit: (a) In one sentence, how do shared and personal knowledge differ? (b) Give one example of personal knowledge becoming shared knowledge. Answers: shared knowledge is built and checked by communities over time, while personal knowledge comes from an individual''s own experience; for example, a single careful observation that is later tested, published, and accepted by others."}]}'::jsonb, 'Keep the pair straight: shared knowledge belongs to communities, personal knowledge belongs to an individual knower.', 13),
  (4, 'What counts as knowledge: justified true belief', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"State the traditional ''justified true belief'' account of knowledge, explain why justification is the hard part, and describe how a knower''s perspective can shape what they count as known. Warm-up: if you guess the answer to a question and happen to be right, do you really know it, or did you just get lucky?"},{"heading":"The idea","text":"For a long time philosophers defined knowledge as justified true belief. On this view, you know something only if three things hold together: the claim is true, you actually believe it, and you have good reasons - justification - for believing it. Truth alone is not enough, because a lucky guess can be true without being known. Belief alone is not enough, because people sincerely believe false things. Justification is what links belief to truth: it is the evidence, reasoning, or reliable method that makes the belief more than a hunch. This is also where the trouble starts. How much justification is enough? Our reasons usually rest on further reasons, which rest on still others, and the chain has to stop somewhere. We cannot prove every starting point, so some knowledge rests on assumptions we trust but cannot fully secure. That is the problem of justification, and it is why honest knowers tend to speak of confidence and good evidence rather than of absolute certainty."},{"heading":"Key ideas & thinkers","text":"In 1963 Edmund Gettier published a short paper showing that justified true belief can still fall short of knowledge: you can have good reasons, hold a true belief, and yet be right only by accident. His examples pushed philosophers to add conditions, such as requiring that the justification not depend on a false step. The deeper lesson for this course is about the knower. Knowledge does not float free of the person holding it. Each knower stands somewhere, shaped by culture, language, training, and experience, and that standpoint, or perspective, influences which questions seem worth asking and which evidence seems to count. Perspective is not simply a flaw; it can sharpen attention. But it can also harden into bias. Confirmation bias leads us to notice and keep evidence that fits what we already think, while quietly discounting what does not. Thinkers from Francis Bacon onward have warned that the mind is not a clean mirror. Good knowers do not pretend to have no perspective; they try to make their own visible and then test it."},{"heading":"Your turn","text":"1) A friend believes it will rain because they read a reliable forecast, and it does rain. Which parts of justified true belief are present? 2) You correctly guess that a coin lands heads. Is that knowledge? Why or why not? 3) Give one reason the chain of justification cannot go on forever. 4) Name one way a knower''s perspective could help, and one way it could mislead. 5) Define confirmation bias in your own words. Answers: 1) Truth (it rained), belief (they believed it), and justification (a reliable forecast) - all three. 2) No; the belief is true but has no justification, so it is luck, not knowledge. 3) Each reason needs a further reason, so without some trusted starting points the chain never ends. 4) It can focus useful attention, but it can also filter out evidence that does not fit. 5) Favoring the evidence that supports what you already believe."},{"heading":"Common mistakes & exit ticket","text":"Mistake: treating a true belief as knowledge even when it rests on no good reason - that ignores justification entirely. Mistake: assuming your own view is the neutral, perspective-free one; everyone reasons from somewhere. Exit: (a) What are the three parts of the traditional definition of knowledge? (b) Why does justification lead to a problem rather than a tidy stopping point? Answers: truth, belief, and justification; because reasons rest on further reasons, so some foundations must be trusted without full proof."}]}'::jsonb, 'Remember the order: a belief must be true and believed and justified - all three together, not any one alone.', 14),
  (5, 'Checkpoint 1', 'quiz', '{"questions":[{"prompt":"A knowledge question is best described as one that is...","options":["closed, with a single lookup answer","open, general, and contestable, about how we know","only ever about mathematics","impossible to discuss sensibly"],"answer":1,"explanation":"Knowledge questions are open and general, inviting reasoned disagreement about knowing itself."},{"prompt":"Traditionally, knowledge is defined as...","options":["any strong feeling","justified true belief","whatever most people accept","a belief printed in a book"],"answer":1,"explanation":"The classic account requires truth, belief, and justification together."},{"prompt":"A true belief held only by a lucky guess is not knowledge because it lacks...","options":["truth","belief","justification","popularity"],"answer":2,"explanation":"Without good reasons linking the belief to the truth, it is luck rather than knowledge."},{"prompt":"The periodic table is an example of...","options":["personal knowledge","shared knowledge","a lucky guess","tacit knowledge"],"answer":1,"explanation":"It was built and checked by a community of knowers over time, so it is shared knowledge."},{"prompt":"Confirmation bias is the tendency to...","options":["forget important facts","favor evidence that fits existing beliefs","trust no one at all","reason without any error"],"answer":1,"explanation":"We tend to seek and keep evidence that confirms what we already think."},{"prompt":"The problem of justification arises because...","options":["reasons rest on further reasons with no final proof","all beliefs turn out to be false","evidence is never allowed in argument","only experts are permitted to reason"],"answer":0,"explanation":"The chain of reasons must stop somewhere, so some starting points are trusted without full proof."}]}'::jsonb, null, 8),
  (6, 'Ways of knowing I: reason, perception, and language', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Explain what a ''way of knowing'' is, and describe three important ones - reason and logic, sense perception, and language - along with the strengths and the limits of each. Warm-up: when you are sure of something, which do you trust more, your senses or your reasoning, and why?"},{"heading":"The idea","text":"Ways of knowing are the tools we use to build and check knowledge. Reason is the tool of logic and inference: from premises we draw conclusions. Deductive reasoning, done correctly, guarantees its conclusion - if all humans are mortal and Socrates is human, then Socrates is mortal. Inductive reasoning generalizes from cases - the Sun has risen every day so far, so it will rise tomorrow - and gives strong support but never total certainty, since the next case could break the pattern. Reason is powerful because its rules are public and can be checked by anyone who follows them. Its limit is that valid reasoning from false premises still yields false conclusions: logic keeps your argument honest, but it cannot supply true starting points on its own. That is why reason works best alongside the other ways of knowing, especially careful observation, rather than in isolation from them."},{"heading":"Key ideas & thinkers","text":"Sense perception - sight, hearing, touch, and the rest - connects us to the world, and much of science begins here. But perception has well-studied limits. Optical illusions fool everyone; expectation shapes what we notice, so two honest witnesses can report different things; and we simply cannot sense much of what exists, from ultraviolet light to very faint sounds. This is why science builds instruments and repeats measurements rather than trusting a single glance. Language is a third way of knowing, and a double-edged one. It lets us store knowledge, pass it across generations, and reason about things we cannot see. Yet the words we have shape the thoughts we form easily; a vague or loaded term can smuggle in assumptions, and translation can shift meaning. The linguists Edward Sapir and Benjamin Whorf argued, controversially, that the language we speak influences how we carve up the world. Whether or not their strong claim holds, few doubt that how a question is worded can steer the answer it receives."},{"heading":"Your turn","text":"1) Is ''All cats are animals; Felix is a cat; so Felix is an animal'' deductive or inductive? 2) Is ''Every swan I have seen is white, so all swans are white'' deductive or inductive, and is it certain? 3) Give one reason not to rely on a single eyewitness. 4) Explain how the wording of a survey question could change the result. 5) Why can a valid argument still reach a false conclusion? Answers: 1) Deductive, and valid. 2) Inductive, and not certain - a single black swan would break it. 3) Perception is shaped by expectation and attention, so honest witnesses can still be wrong. 4) A loaded or leading phrase nudges people toward one answer. 5) Validity only guarantees the conclusion if the premises are true, so false premises can give a false conclusion."},{"heading":"Common mistakes & exit ticket","text":"Mistake: thinking induction proves its conclusion the way deduction does - it only supports it. Mistake: treating your senses as a perfect recording of reality. Exit: (a) What is the key difference between deductive and inductive reasoning? (b) Name one way language can shape knowledge. Answers: deduction guarantees its conclusion when the premises are true, while induction generalizes and gives only strong support; language can frame or limit thought, so the words of a question can steer its answer."}]}'::jsonb, 'Deductive and inductive are not interchangeable - deduction guarantees its conclusion, induction only supports it.', 14),
  (7, 'Ways of knowing II: emotion, intuition, imagination, faith, memory', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Describe five further ways of knowing - emotion, intuition, imagination, faith, and memory - and weigh what each contributes to knowledge and where each can lead us astray. Warm-up: can a strong feeling ever be a reliable guide to what is true, or is it always just noise to set aside?"},{"heading":"The idea","text":"Beyond reason, perception, and language, this course considers ways of knowing that are easy to dismiss but hard to do without. Emotion can distort judgment, yet it also directs our attention and signals what matters; fear can warn us of real danger, and moral outrage can flag an injustice worth investigating. Intuition is the sense of knowing something without conscious reasoning - the quick read an experienced nurse or chess player seems to have. Research suggests such intuition is often compressed expertise: reliable in familiar settings and much less reliable in unfamiliar ones. Imagination lets us form possibilities we have never observed, run thought experiments, and model what might be; a great deal of science and art depends on it. None of these replaces evidence, but each shapes which questions we ask and which answers we are willing to consider. The balanced view is not to crown feeling or hunch as truth, nor to banish them, but to notice their role and check their suggestions against the other ways of knowing."},{"heading":"Key ideas & thinkers","text":"Faith, in this course, means commitment that runs ahead of complete proof - and in that broad sense it reaches well beyond religion. We rely on trust whenever we accept a doctor''s diagnosis, a map, or a report we cannot personally verify, because no one can check everything first-hand. The question this course presses is not whether to trust, but how to trust well: on what grounds, and how open we stay to revising that trust. Memory stitches knowledge across time; without it there is no learning at all. Yet research by psychologists such as Elizabeth Loftus shows that memory is reconstructive, not a recording - it can be edited by later suggestion, and people can hold vivid, confident memories of events that did not happen as recalled. This is why historians and courts prize corroborating documents and multiple accounts over a single remembered story. Taken together, these ways of knowing show that human knowing is rich and fallible at once, which is exactly why cross-checking matters so much."},{"heading":"Your turn","text":"1) Give one example where emotion could help a knower and one where it could mislead. 2) When is intuition most trustworthy? 3) What is a thought experiment, and which way of knowing does it draw on? 4) Explain the broad sense of ''faith'' used here, with an everyday example. 5) Why do courts prefer several accounts to one confident memory? Answers: 1) Fear can warn of danger (help); anger can bias a judgment (mislead). 2) In familiar areas where a person has deep, tested experience. 3) An imagined scenario used to reason about consequences, drawing on imagination. 4) Trusting a claim before full proof, such as accepting a train timetable you have not checked yourself. 5) Because memory is reconstructive and can be confidently wrong, so corroboration guards against error."},{"heading":"Common mistakes & exit ticket","text":"Mistake: treating a strong gut feeling as proof, or treating all feelings as worthless noise - both skip the step of checking. Mistake: trusting memory as if it were an exact recording. Exit: (a) Why is intuition reliable in some settings and not in others? (b) In what sense is memory reconstructive? Answers: intuition is compressed experience, so it is dependable in familiar areas but risky in unfamiliar ones; memory is rebuilt each time we recall and can be reshaped by suggestion, so it is not a perfect record."}]}'::jsonb, 'Treat emotion, intuition, and the rest as sources of questions to test, not as proof on their own.', 14),
  (8, 'Key terms', 'vocab', '{"items":[{"term":"epistemology","translation":"the branch of philosophy that studies knowledge - what it is and how we get it","example":"Asking ''what makes a belief count as knowledge?'' is an epistemology question."},{"term":"knowledge question","translation":"an open, general, contestable question about how knowledge is built, judged, or justified","example":"''How do historians decide which sources to trust?'' is a knowledge question, not a simple fact."},{"term":"justified true belief","translation":"the traditional definition of knowledge as a belief that is true and supported by good reasons","example":"A right answer with no reasons behind it is a true belief but not justified true belief."},{"term":"shared knowledge","translation":"knowledge built and checked by a community of knowers over time","example":"The periodic table is shared knowledge that no single person created."},{"term":"personal knowledge","translation":"knowledge an individual gains through their own experience, practice, and reflection","example":"Knowing how to keep your balance on a bicycle is personal knowledge."},{"term":"way of knowing","translation":"a tool through which knowledge is built or checked, such as reason, perception, or language","example":"Sense perception is the way of knowing that connects us most directly to the world."},{"term":"area of knowledge","translation":"a large field with its own questions, methods, and standards of proof","example":"History and mathematics are areas of knowledge that test claims very differently."},{"term":"falsifiability","translation":"the quality of a claim that could be shown false by some possible observation","example":"Popper argued that a claim is scientific only if it is falsifiable."}]}'::jsonb, null, 10),
  (9, 'Areas of knowledge and evaluating claims', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Name the main areas of knowledge - the natural sciences, the human sciences, history, mathematics, the arts, and ethics - describe how each builds and tests knowledge, and apply a simple method for evaluating any claim. Warm-up: would you expect a historian and a chemist to prove things in the same way?"},{"heading":"The idea","text":"An area of knowledge is a large field with its own questions, methods, and standards of proof. The natural sciences build knowledge through observation, hypothesis, and repeatable experiment, and they prize predictions that could fail but do not. The human sciences, such as economics, psychology, and sociology, study people, where experiments are harder and subjects react to being studied, so they lean on careful models, statistics, and awareness of bias. History interprets the past from surviving evidence; it cannot rerun events, so it cross-checks sources and reasons about their reliability and motive. Mathematics is unusual: it proves claims by deduction from axioms, reaching certainty within its own system rather than by observing the world. The arts build a different kind of knowledge, offering insight, meaning, and ways of seeing that resist being reduced to plain fact. Ethics asks what we ought to do, weighing principles, consequences, and character. Seeing these side by side shows there is no single method for all knowledge - good thinking means using the standards that fit the field."},{"heading":"Key ideas & thinkers","text":"Comparing areas of knowledge sharpens the central questions of the course. Why does mathematics feel certain while the human sciences deal in probabilities? Karl Popper argued that a claim is scientific only if it is falsifiable - if some possible observation could show it to be false - which helps mark science off from claims that explain everything and so predict nothing. Thomas Kuhn added that science also moves through shared frameworks, or paradigms, that occasionally shift. In history, the gap between evidence and interpretation means two honest historians can read the same documents differently. In the arts and in ethics, knowledge is contested in yet other ways, turning on judgment, value, and perspective rather than on measurement. None of this means that anything goes. It means each area has earned methods for separating stronger claims from weaker ones, and part of being knowledgeable is knowing which method a given question calls for."},{"heading":"Your turn","text":"Apply a quick check to a claim by asking: What exactly is claimed? What is the evidence? How reliable is the source? Which area of knowledge is it, and does the evidence fit that area''s standards? 1) ''A new study shows chocolate cures colds.'' List two questions you would ask. 2) Which area tests claims by repeatable experiment? 3) Which area proves claims by deduction from axioms? 4) Why can two historians disagree while both are being careful? 5) Name one reason to be cautious about a single dramatic statistic. Answers: 1) How large and well designed was the study, and who funded or reported it? 2) The natural sciences. 3) Mathematics. 4) Evidence underdetermines interpretation, so reasonable readings can differ. 5) One result may not replicate, may be cherry-picked, or may be reported with no context."},{"heading":"Common mistakes & exit ticket","text":"Mistake: judging every field by the standards of one - expecting history to run experiments, or demanding that the arts yield measurable proof. Mistake: accepting a claim because it is confident, popular, or often repeated, rather than checking the evidence and the source. Exit: (a) Name three areas of knowledge and one way each tests claims. (b) List two questions from the quick check for evaluating a claim. Answers: for example, the natural sciences test by repeatable experiment, history by cross-checking sources, and mathematics by deductive proof; two useful questions are ''what is the evidence?'' and ''how reliable is the source?''"}]}'::jsonb, 'Match the method to the field - do not judge history by the standards of chemistry, or the arts by those of mathematics.', 15),
  (10, 'Checkpoint 2', 'quiz', '{"questions":[{"prompt":"Which kind of reasoning guarantees its conclusion when the premises are true?","options":["induction","deduction","guessing","perception"],"answer":1,"explanation":"Valid deduction guarantees a true conclusion whenever the premises are true."},{"prompt":"A key limit of sense perception is that...","options":["it is always perfectly exact","expectation and illusion can distort it","only machines are able to use it","it never needs any checking"],"answer":1,"explanation":"Illusions and expectation can mislead the senses, so observations are checked and repeated."},{"prompt":"Research suggests that human memory is...","options":["a perfect recording","reconstructive and open to suggestion","never of any use","the same thing as imagination"],"answer":1,"explanation":"Memory is rebuilt on recall and can be edited by later suggestion, so it is not an exact record."},{"prompt":"Popper argued that a claim is scientific only if it is...","options":["popular","falsifiable","ancient","untestable"],"answer":1,"explanation":"A scientific claim must be open to being shown false by some possible observation."},{"prompt":"Mathematics mainly establishes its claims by...","options":["repeatable experiment","deductive proof from axioms","public opinion","eyewitness reports"],"answer":1,"explanation":"Mathematics proves results by deduction within its system rather than by observing the world."},{"prompt":"A sound first question when evaluating a claim is...","options":["is it popular?","what is the evidence and how reliable is the source?","who said it most loudly?","is it brand new?"],"answer":1,"explanation":"Begin with the evidence and the reliability of the source, not with popularity or volume."}]}'::jsonb, null, 8)
) as v(pos, title, kind, body, notes, mins)
where not exists (
  select 1 from public.lessons l
  where l.course_id = 'bbbb0005-0000-4000-8000-000000000020' and l.position = v.pos
);
